class Solution {
    public String addStrings(String num1, String num2) {
        StringBuilder reversed = new StringBuilder();
        int i = num1.length() - 1;
        int j = num2.length() - 1;
        int carry = 0;
        while (i >= 0 || j >= 0 || carry > 0) {
            int sum = carry;
            if (i >= 0) {
                sum += num1.charAt(i--) - '0';
            }
            if (j >= 0) {
                sum += num2.charAt(j--) - '0';
            }
            reversed.append((char) ('0' + sum % 10));
            carry = sum / 10;
        }
        return reversed.reverse().toString();
    }
}

class Solution {
    public String addStrings(String num1, String num2) {
        int maxLength = Math.max(num1.length(), num2.length());
        char[] buffer = new char[maxLength + 1];
        int write = buffer.length - 1;
        int i = num1.length() - 1;
        int j = num2.length() - 1;
        int carry = 0;
        while (i >= 0 || j >= 0) {
            int sum = carry;
            if (i >= 0) {
                sum += num1.charAt(i--) - '0';
            }
            if (j >= 0) {
                sum += num2.charAt(j--) - '0';
            }
            buffer[write--] = (char) ('0' + sum % 10);
            carry = sum / 10;
        }
        buffer[write] = (char) ('0' + carry);
        return carry == 0 ? new String(buffer, 1, maxLength) : new String(buffer);
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public String addStrings(String num1, String num2) {
        Deque<Character> digits = new ArrayDeque<>();
        int i = num1.length() - 1;
        int j = num2.length() - 1;
        int carry = 0;
        while (i >= 0 || j >= 0 || carry > 0) {
            int sum = carry;
            if (i >= 0) {
                sum += num1.charAt(i--) - '0';
            }
            if (j >= 0) {
                sum += num2.charAt(j--) - '0';
            }
            digits.addFirst((char) ('0' + sum % 10));
            carry = sum / 10;
        }
        StringBuilder answer = new StringBuilder(digits.size());
        for (char digit : digits) {
            answer.append(digit);
        }
        return answer.toString();
    }
}

class Solution {
    public String addStrings(String num1, String num2) {
        int maxLength = Math.max(num1.length(), num2.length());
        int[] columns = new int[maxLength + 1];

        int offset = columns.length - num1.length();
        for (int i = 0; i < num1.length(); i++) {
            columns[offset + i] += num1.charAt(i) - '0';
        }
        offset = columns.length - num2.length();
        for (int i = 0; i < num2.length(); i++) {
            columns[offset + i] += num2.charAt(i) - '0';
        }

        for (int i = columns.length - 1; i > 0; i--) {
            columns[i - 1] += columns[i] / 10;
            columns[i] %= 10;
        }

        StringBuilder answer = new StringBuilder(columns.length);
        int start = columns[0] == 0 ? 1 : 0;
        for (int i = start; i < columns.length; i++) {
            answer.append((char) ('0' + columns[i]));
        }
        return answer.toString();
    }
}

class Solution {
    private static final int BASE = 10000;
    private static final int WIDTH = 4;

    public String addStrings(String num1, String num2) {
        StringBuilder reversedChunks = new StringBuilder();
        int i = num1.length();
        int j = num2.length();
        int carry = 0;
        while (i > 0 || j > 0 || carry > 0) {
            int start1 = Math.max(0, i - WIDTH);
            int start2 = Math.max(0, j - WIDTH);
            int a = parseChunk(num1, start1, i);
            int b = parseChunk(num2, start2, j);
            int sum = a + b + carry;
            int chunk = sum % BASE;
            carry = sum / BASE;
            boolean hasMoreHighChunks = start1 > 0 || start2 > 0 || carry > 0;

            if (hasMoreHighChunks) {
                appendPaddedReverse(reversedChunks, chunk);
            } else {
                appendReverse(reversedChunks, chunk);
            }
            i = start1;
            j = start2;
        }
        return reversedChunks.reverse().toString();
    }

    private int parseChunk(String s, int start, int end) {
        int value = 0;
        for (int i = start; i < end; i++) {
            value = value * 10 + (s.charAt(i) - '0');
        }
        return value;
    }

    private void appendPaddedReverse(StringBuilder builder, int value) {
        for (int k = 0; k < WIDTH; k++) {
            builder.append((char) ('0' + value % 10));
            value /= 10;
        }
    }

    private void appendReverse(StringBuilder builder, int value) {
        if (value == 0) {
            builder.append('0');
            return;
        }
        while (value > 0) {
            builder.append((char) ('0' + value % 10));
            value /= 10;
        }
    }
}
